@extends('layouts.admin') @section('title','Usuários') @section('content')<div class="page-heading"><div><h1>Usuários</h1><p class="text-muted">Apenas administradores podem criar, alterar papéis e status.</p></div><a class="admin-button" href="{{ route('admin.users.create') }}"><i class="fas fa-plus"></i> Novo usuário</a></div><div class="admin-card"><table class="admin-table"><tr><th>Nome</th><th>E-mail</th><th>Papel</th><th>Status</th><th></th></tr>@foreach($users as $user)<tr><form method="post" action="{{ route('admin.users.update',$user) }}">@csrf @method('PUT')<td><input name="name" value="{{ $user->name }}"></td><td>{{ $user->email }}</td><td><select name="role"><option value="administrator" @selected($user->role==='administrator')>Administrator</option><option value="editor" @selected($user->role==='editor')>Editor</option></select></td><td><select name="status"><option value="active" @selected($user->status==='active')>Ativo</option><option value="inactive" @selected($user->status==='inactive')>Inativo</option></select></td><td class="actions"><button class="admin-button" type="submit">Salvar</button></form>@unless($user->is(auth()->user()))<form method="post" action="{{ route('admin.users.destroy',$user) }}" onsubmit="return confirm('Excluir este usuário?')">@csrf @method('DELETE')<button class="icon-action" title="Excluir"><i class="fas fa-trash"></i></button></form>@endunless</td></tr>@endforeach</table>{{ $users->links() }}</div>@endsection
